package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.*;
import com.lianxibu.site.service.articles.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BooleanSupplier;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Actual whole day allocation -> INPUT/request. Settings/policy ports are explicitly fictional; no analysis model transport. */
class CatalogDayAnalysisPreparationTest {
    boolean mysql(){return false;}
    CatalogAnalysisInputProfileTest helper(){return new CatalogAnalysisInputProfileTest(){@Override boolean mysql(){return CatalogDayAnalysisPreparationTest.this.mysql();}};}
    AnalysisPublicMetadataEnricher metadata(CatalogAnalysisInputProfileTest.Built built){var source=built.data().f().f.source;var members=new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(source));return new AnalysisPublicMetadataEnricher(new EntityInputEvidenceService(new JdbcEntityDedup(source),members),new ArticlePublicEvidenceService(new JdbcArticlePublicEvidence(source),members));}
    GenerationFlowService.SettingsSnapshotSource settings(){return ()->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());return helper().settings;};}
    CatalogDayAnalysisPreparationService service(CatalogAnalysisInputProfileTest.Built built,CatalogDayAnalysisInputPermitService permit,GenerationFlowService.SettingsSnapshotSource settings,GenerationRequestBuilder requests,Clock clock,BooleanSupplier allowed){var f=built.data().f().f;return new CatalogDayAnalysisPreparationService(f.source,new CatalogAnalysisPreparedInputService(f.source,f.tx,mock(Clock.class),f.category),permit,f.writes,settings,metadata(built),requests,clock,allowed,f.category);}
    CatalogDayAnalysisPreparationService service(CatalogAnalysisInputProfileTest.Built built){return service(built,built.provider(),settings(),new GenerationRequestBuilder(),Clock.fixed(built.data().outer().completed.plusSeconds(120),ZoneOffset.UTC),()->true);}
    @Test void FourActualCategoriesFreezeCompleteInputRequestAndOneNativeRootWithoutSending(){for(String category:List.of("agent","skill","workflow","model")){var built=helper().fixture(category,false);var data=built.data();int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var service=service(built);var stored=service.prepare(data.outer().day,data.receipt().entityId());var input=stored.input();assertEquals(1,input.generation());assertEquals(category+"_analysis",CanonicalJson.parse(input.snapshotJson()).get("stage").asText());assertEquals(data.receipt().json(),stored.reservation().json());assertEquals(1,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,data.receipt().intentId()));assertEquals(1,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE root_job_id=? AND record_kind='ai_attempt'",Integer.class,input.ownerId()));assertEquals(0,data.f().f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,input.ownerId()));assertEquals("queued",input.state());assertEquals("complete",input.coverageState());assertEquals(input.inputHash(),CanonicalJson.parse(input.requestJson()).get("input_hash").asText());assertEquals(input,service.prepare(data.outer().day,data.receipt().entityId()).input());assertTrue(data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class)>jobs);assertEquals(2,data.f().f.sends);}}
    @Test void ActualPositiveAliasGenerationUsesOldSuccessfulRootAndAllOriginalMembers(){var built=helper().fixture("agent",true);var data=built.data();var input=service(built).prepare(data.outer().day,data.receipt().entityId()).input();assertEquals(2,input.generation());assertEquals(2,CanonicalJson.parse(input.snapshotJson()).get("members").size());assertEquals("fictional-analysis",CatalogAnalysisInputProfile.complete(CanonicalJson.parse(input.snapshotJson())).command().applicationContext().contentId());assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,data.f().f.jdbc.queryForObject("SELECT supersedes_job_id FROM jobs WHERE id=?",String.class,input.ownerId()));assertEquals(2,data.f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,data.f().f.sends);}
    @Test void OriginalReceiptReplaySkipsRemovedCurrentTablesAndAllMutableDependencies(){var built=helper().fixture("model",false);var data=built.data();var input=service(built).prepare(data.outer().day,data.receipt().entityId()).input();int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);for(String table:List.of("sources","source_run_items","analyzed_entities","contents"))data.f().f.jdbc.execute("DROP TABLE "+table);var permits=mock(CatalogDayAnalysisInputPermitService.class);var settings=mock(GenerationFlowService.SettingsSnapshotSource.class);var requests=mock(GenerationRequestBuilder.class);var clock=mock(Clock.class);var allowed=mock(BooleanSupplier.class);assertEquals(input,service(built,permits,settings,requests,clock,allowed).prepare(data.outer().day,data.receipt().entityId()).input());verifyNoInteractions(permits,settings,requests,clock,allowed);assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,data.f().f.sends);}
    @Test void RequestConstructionIsOutsideWriterAndPreferenceChangeRejectsWholeFirstFreeze(){var built=helper().fixture("skill",false);var data=built.data();int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var requests=spy(new GenerationRequestBuilder());doAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return call.callRealMethod();}).when(requests).build(any(),anyString(),anyString());var reads=new AtomicInteger();GenerationFlowService.SettingsSnapshotSource settings=()->reads.incrementAndGet()==1?helper().settings:new FrozenGenerationSettings(4,List.of("fictional-changed"),List.of());assertThrows(RuntimeException.class,()->service(built,built.provider(),settings,requests,Clock.fixed(data.outer().completed.plusSeconds(120),ZoneOffset.UTC),()->true).prepare(data.outer().day,data.receipt().entityId()));assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(0,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,data.receipt().intentId()));var input=service(built,built.provider(),settings(),requests,Clock.fixed(data.outer().completed.plusSeconds(120),ZoneOffset.UTC),()->true).prepare(data.outer().day,data.receipt().entityId());assertNotNull(input);verify(requests,times(1)).build(any(),anyString(),anyString());assertEquals(2,data.f().f.sends);}
    @Test void NativeReceiptFailureRollsBackEveryInputPartRootAttemptAndLineage(){var built=helper().fixture("workflow",false);var data=built.data();int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);data.f().f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_analysis_prepare_failure CHECK(target_type IS NULL OR target_type<>'generation_prepare' OR operator_id<>'catalog-analysis-coordinator')");assertThrows(RuntimeException.class,()->service(built).prepare(data.outer().day,data.receipt().entityId()));assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(0,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,data.receipt().intentId()));assertEquals(1,data.f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals("waiting_input",data.f().f.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,data.receipt().intentId()));assertEquals(2,data.f().f.sends);}
    @Test void CapacityPauseCurrentMemberChangeAndBeforeReservationTimeCannotFreeze(){var built=helper().fixture("agent",false);var data=built.data();int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertThrows(GenerationFlowService.CapacityGuarded.class,()->service(built,built.provider(),settings(),new GenerationRequestBuilder(),Clock.fixed(data.outer().completed.plusSeconds(120),ZoneOffset.UTC),()->false).prepare(data.outer().day,data.receipt().entityId()));assertThrows(RuntimeException.class,()->service(built,built.provider(),settings(),new GenerationRequestBuilder(),Clock.fixed(data.receipt().reservedAt().minusSeconds(1),ZoneOffset.UTC),()->true).prepare(data.outer().day,data.receipt().entityId()));data.f().f.jdbc.update("UPDATE source_run_items SET evidence_hash=?",new byte[32]);assertThrows(RuntimeException.class,()->service(built).prepare(data.outer().day,data.receipt().entityId()));assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,data.f().f.sends);}
    @Test void TwoActualCallersFreezeOneOriginalEvenWhenSecondCaptureBecomesStale() throws Exception{var built=helper().fixture("model",false);var data=built.data();var permits=spy(built.provider());var barrier=new CyclicBarrier(2);doAnswer(call->{barrier.await(5,TimeUnit.SECONDS);return built.captured();}).when(permits).capture(data.outer().day,data.receipt().entityId());var coordinator=service(built,permits,settings(),new GenerationRequestBuilder(),Clock.fixed(data.outer().completed.plusSeconds(120),ZoneOffset.UTC),()->true);try(var pool=Executors.newFixedThreadPool(2)){var first=pool.submit(()->coordinator.prepare(data.outer().day,data.receipt().entityId()));var second=pool.submit(()->coordinator.prepare(data.outer().day,data.receipt().entityId()));assertEquals(first.get(15,TimeUnit.SECONDS).input(),second.get(15,TimeUnit.SECONDS).input());}assertEquals(1,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,data.receipt().intentId()));assertEquals(1,data.f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,data.f().f.sends);}
    @Test void ActualCommitAckLossRecoversOriginalWholeInputWithoutAnotherAttempt(){var built=helper().fixture("skill",false);var data=built.data();var requests=spy(new GenerationRequestBuilder());doAnswer(call->{var request=call.callRealMethod();data.f().f.tx.ackLost=true;return request;}).when(requests).build(any(),anyString(),anyString());var coordinator=service(built,built.provider(),settings(),requests,Clock.fixed(data.outer().completed.plusSeconds(120),ZoneOffset.UTC),()->true);var stored=coordinator.prepare(data.outer().day,data.receipt().entityId());assertEquals(stored.input(),coordinator.prepare(data.outer().day,data.receipt().entityId()).input());assertEquals(1,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,data.receipt().intentId()));assertEquals(1,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE root_job_id=? AND record_kind='ai_attempt'",Integer.class,stored.input().ownerId()));verify(requests,times(1)).build(any(),anyString(),anyString());assertEquals(2,data.f().f.sends);}
    @Test void MandatoryClosedConstructionDoesNoIo(){var source=mock(DataSource.class);var originals=mock(CatalogAnalysisPreparedInputService.class);var permits=mock(CatalogDayAnalysisInputPermitService.class);var writes=mock(SharedWriteExecutor.class);var settings=mock(GenerationFlowService.SettingsSnapshotSource.class);var metadata=mock(AnalysisPublicMetadataEnricher.class);var requests=mock(GenerationRequestBuilder.class);var clock=mock(Clock.class);var allowed=mock(BooleanSupplier.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisPreparationService(source,originals,permits,writes,settings,metadata,requests,clock,allowed,category));verifyNoInteractions(source,originals,permits,writes,settings,metadata,requests,clock,allowed);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisPreparationService(source,originals,permits,writes,settings,metadata,requests,clock,allowed,"news_tech"));}
}
